class Solution {
    unordered_map<string, string> parent;

    string findRoot(const string& word) {
        if (!parent.count(word)) {
            parent[word] = word;
        }
        if (parent[word] != word) {
            parent[word] = findRoot(parent[word]);
        }
        return parent[word];
    }

public:
    bool areSentencesSimilarTwo(vector<string>& sentence1,
                                vector<string>& sentence2,
                                vector<vector<string>>& similarPairs) {
        if (sentence1.size() != sentence2.size()) {
            return false;
        }
        parent.clear();
        for (const auto& pair : similarPairs) {
            string a = findRoot(pair[0]);
            string b = findRoot(pair[1]);
            parent[a] = b;
        }
        for (int i = 0; i < static_cast<int>(sentence1.size()); ++i) {
            if (findRoot(sentence1[i]) != findRoot(sentence2[i])) {
                return false;
            }
        }
        return true;
    }
};
